        {
            if (Session["Role"] != "Admin")
            {
                return Redirect("login.asp");
            }

            var reportYear = year;

            using (var connection = new SqlConnection(_dataSource.ConnectionString))
            {
                await connection.OpenAsync(cancellationToken);

                using (var command = connection.CreateCommand())
                {
                    command.CommandText = "SELECT Region, SUM(Amount) AS Total FROM Sales WHERE YEAR(SaleDate) = @Year GROUP BY Region";
