namespace Migrated.Pages;

public sealed class EmployeeListModel(DbDataSource dataSource) : PageModel
{
    public List<EmployeeRow> Employees { get; private set; } = new();

    public async Task<IActionResult> OnGetAsync(string department, CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand("SELECT FirstName, LastName, Title FROM Employees WHERE Department = @dept ORDER BY LastName");
        var parameter = command.CreateParameter();
        parameter.ParameterName = "@dept";
        parameter.Value = department;
        command.Parameters.Add(parameter);
        using (var reader = await command.ExecuteReaderAsync(cancellationToken))
        {
            Employees = new List<EmployeeRow>();
            while (await reader.ReadAsync(cancellationToken))
            {
                Employees.Add(new EmployeeRow(
                    reader.GetString(0),
                    reader.GetString(1),
                    reader.GetString(2)
                ));
            }
        }
        return Page();
    }
}

public sealed record EmployeeRow(string FirstName, string LastName, string Title);

using System.Data.Common;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;

namespace Migrated.Pages;

public sealed class NewsletterModel(DbDataSource dataSource) : PageModel
{
    public string? Email { get; private set; }
    public string? FullName { get; private set; }

    public async Task<IActionResult> OnPostAsync(string email, string fullName, CancellationToken cancellationToken)
    {
        Email = email;
        FullName = fullName;
        return await SaveSubscriptionAsync(cancellationToken);
    }

    private async Task<IActionResult> SaveSubscriptionAsync(CancellationToken cancellationToken)
    {
        await using var command = dataSource.CreateCommand("INSERT INTO Subscribers (Email, FullName, CreatedAt) VALUES (@email, @fullName, GETDATE())");
        var parameterEmail = command.CreateParameter();
        parameterEmail.ParameterName = "@email";
        parameterEmail.Value = Email;
        command.Parameters.Add(parameterEmail);

        var parameterFullName = command.CreateParameter();
        parameterFullName.ParameterName = "@fullName";
        parameterFullName.Value = FullName;
        command.Parameters.Add(parameterFullName);

        await command.ExecuteNonQueryAsync(cancellationToken);

        return RedirectToPage("thanks");
    }
}

